//  concepts: CompletableFuture.exceptionallyCompose · lazy fallback futures · CompletionException on join
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

class Exercise {

    /** The primary's value, or — only when it failed — the future the backup supplies. */
    static CompletableFuture<String> withBackup(CompletableFuture<String> primary, Supplier<CompletableFuture<String>> backup) {
        throw new UnsupportedOperationException("TODO: compose on the error path only, creating the backup there");
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a healthy primary answers", () ->
            eq(withBackup(CompletableFuture.completedFuture("primary-row"), () -> CompletableFuture.completedFuture("replica-row")).join(),
                "primary-row"));
        test("a healthy primary never asks the backup", () -> {
            var calls = new AtomicInteger();
            withBackup(CompletableFuture.completedFuture("primary-row"), () -> {
                calls.incrementAndGet();
                return CompletableFuture.completedFuture("replica-row");
            }).join();
            eq(calls.get(), 0);
        });
        test("a failed primary asks the backup exactly once", () -> {
            var calls = new AtomicInteger();
            eq(withBackup(CompletableFuture.failedFuture(new IllegalStateException("primary down")), () -> {
                calls.incrementAndGet();
                return CompletableFuture.completedFuture("replica-row");
            }).join(), "replica-row");
            eq(calls.get(), 1);
        });
        test("a failed backup surfaces through join (boundary)", () -> {
            var result = withBackup(CompletableFuture.failedFuture(new IllegalStateException("primary down")),
                () -> CompletableFuture.failedFuture(new IllegalStateException("replica down")));
            var ex = raises(CompletionException.class, () -> result.join());
            eq(ex.getCause().getMessage(), "replica down");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

