import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

class Exercise {

    /** thenApply (logs "apply", passes the value) then handle (logs "handle", -1 on failure). */
    static CompletableFuture<Integer> tagged(CompletableFuture<Integer> f, List<String> log) {
        return f.thenApply(v -> {
            log.add("apply");
            return v;
        }).handle((v, ex) -> {
            log.add("handle");
            return ex != null ? -1 : v;
        });
    }

    /** 100 / value via thenApply, then handle: "ok:<q>", or "<SimpleName>: <message>" of the ORIGINAL failure. */
    static CompletableFuture<String> quotientOrFailure(CompletableFuture<Integer> f) {
