import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

class Exercise {

    /** "ok:<value>" or "err:<message of the original failure>" per input, in input order, once EVERY input has settled. */
    static CompletableFuture<List<String>> settleAll(List<CompletableFuture<String>> fs) {
        List<CompletableFuture<String>> outcomes = fs.stream()
            .map(f -> f.handle((v, ex) -> ex == null ? "ok:" + v : "err:" + original(ex).getMessage()))
            .toList();
        return CompletableFuture.allOf(outcomes.toArray(new CompletableFuture<?>[0]))
            .thenApply(ignored -> outcomes.stream().map(CompletableFuture::join).toList());
    }

    private static Throwable original(Throwable ex) {
        return ex instanceof CompletionException && ex.getCause() != null ? ex.getCause() : ex;
    }

    // ─── tests ───────────────────────────────────────────────────────────
